import{z as i,x as s,o as e,c as l,q as A,j as t,D as a,d as o,s as B,S as r}from"./chunks/framework.C8m1ZpeB.js";const D=JSON.parse('{"title":"预期的管理与传导","description":"","frontmatter":{"title":"预期的管理与传导","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/mt-expectations-transmission.md","filePath":"econ/mt-expectations-transmission.md","lastUpdated":1791413859000}'),p={name:"econ/mt-expectations-transmission.md"};function d(c,E,h,m,C,_){const n=s("Mermaid");return e(),l("div",null,[E[2]||(E[2]=A('<h1 id="预期的管理与传导" tabindex="-1">预期的管理与传导 <a class="header-anchor" href="#预期的管理与传导" aria-label="Permalink to &quot;预期的管理与传导&quot;">​</a></h1><div class="epigraph"><p>央行公告同时做两件事：告诉公众通胀会是什么，以及替公众决定该把预期协调到哪一点；第二件事常常比第一件更有效力。</p><footer>—— 据 Morris–Shin 2002；Woodford, Interest and Prices, 2003 整理</footer></div><p><a href="/econ/mt-policy-rules">上一课</a>把承诺写成反应函数，并要求 \\(\\phi_\\pi \\gt 1\\) 来保住均衡唯一。但反应函数作用的对象不是物价本身，而是公众的预期：规则约束的是央行自己的行为，传导要穿过家庭与企业的预期形成。基线课的<a href="/econ/expectations-management">预期管理与沟通</a>与<a href="/econ/inflation-anchoring">通胀预期锚定</a>讲了沟通实践与锚定的经验事实；本课深化两件事——预期的形成模型，与传导管道的逐段分解。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同样降息一百个基点，有时需求明显起振，有时悄无声息。差别藏在<a href="/econ/new-keynesian">新凯恩斯</a>消费欧拉方程里：当期消费取决于未来消费路径与<strong>整条</strong>预期实际利率路径，不是当期一期的利率。于是传导的强弱取决于三个状态量：预期通胀 \\(E_t\\pi_{t+1}\\) 是否锚住、未来政策利率路径的预期、以及家庭结构决定的消费平滑能力。<a href="/econ/fg-puzzle">前瞻指引之谜</a>已经记录了标准模型的病灶：完美平滑的代表性家庭把遥远的承诺利率也放大成当期需求，效应「异常大」。</p><p><span class="marginnote">「前瞻指引」翻译成大白话：央行提前告诉你「未来一段时间利率会保持很低」。它作用的对象是你对未来利率路径的猜测，而不是今天的利率本身——长端利率正是这条预期路径的贴现和。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>把管道拆成三段，每段单独核账。</p><p><strong>利率的期限段</strong>：政策利率只管最短端，长端利率是预期短端路径的贴现和加期限溢价。传导的第一步是移动整条预期路径——指引、再投资承诺、资产购买都在做这件事，程度取决于可信性。</p><p><span class="marginnote">数字实例：市场预计未来五年短期利率平均为 2%，再加 0.5% 的期限溢价，五年期利率约为 2.5%。央行只要让公众相信「未来五年平均短端利率将低 0.3%」，长端就能立刻降 0.3%——今天的政策利率一动不动也行。</span></p><p><strong>预期的锚定段</strong>：锚住时，名义利率的每一单位变动几乎一对一转化为实际利率变动；脱锚时，宽松会被通胀预期上升吃掉一部分。锚定因此不是修辞，是实际利率弹性的乘数。</p><p><strong>家庭结构段</strong>：在异质agent模型里（<a href="/econ/hank">HANK</a>），消费对利率的直接弹性集中在持有流动资产的家庭，多数家庭靠劳动收入渠道感受政策；前瞻指引的跨期替代效应大减，收入与就业效应接管传导。标准模型对指引的过度放大，在分布维度上得到修正。</p>',12)),(e(),t(r,null,{default:a(()=>[B(n,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20RULE%5B%22%E6%94%BF%E7%AD%96%E5%88%A9%E7%8E%87%E4%B8%8E%E8%A7%84%E5%88%99%22%5D%20--%3E%20PATH%5B%22%E9%A2%84%E6%9C%9F%E7%9F%AD%E7%AB%AF%E5%88%A9%E7%8E%87%E8%B7%AF%E5%BE%84%22%5D%0A%20%20PATH%20--%3E%20LONG%5B%22%E9%95%BF%E7%AB%AF%E5%88%A9%E7%8E%87%EF%BC%9A%E8%B4%B4%E7%8E%B0%E5%92%8C%E5%8A%A0%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20ANCHOR%5B%22%E9%80%9A%E8%83%80%E9%A2%84%E6%9C%9F%E9%94%9A%E5%AE%9A%22%5D%20--%3E%20REAL%5B%22%E5%AE%9E%E9%99%85%E5%88%A9%E7%8E%87%20%3D%20%E5%90%8D%E4%B9%89%20-%20%E9%A2%84%E6%9C%9F%E9%80%9A%E8%83%80%22%5D%0A%20%20LONG%20--%3E%20REAL%0A%20%20REAL%20--%3E%20HET%7B%22%E5%AE%B6%E5%BA%AD%E7%BB%93%E6%9E%84%22%7D%0A%20%20HET%20--%3E%7C%22%E5%B9%B3%E6%BB%91%E8%83%BD%E5%8A%9B%E5%BC%BA%22%7C%20BIG%5B%22%E8%B7%A8%E6%9C%9F%E6%9B%BF%E4%BB%A3%E4%B8%BB%E5%AF%BC%22%5D%0A%20%20HET%20--%3E%7C%22%E5%A4%9A%E6%95%B0%E5%AE%B6%E5%BA%AD%E5%8F%97%E6%B5%81%E5%8A%A8%E6%80%A7%E7%BA%A6%E6%9D%9F%22%7C%20INC%5B%22%E6%94%B6%E5%85%A5%E4%B8%8E%E5%B0%B1%E4%B8%9A%E6%B8%A0%E9%81%93%E4%B8%BB%E5%AF%BC%22%5D%0A"})]),fallback:a(()=>[...E[0]||(E[0]=[o(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=A('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>预期形成的模型决定锚定该怎么读。理性预期是基准，但它不解释漂移：<a href="/econ/adaptive-learning">适应性预期与学习</a>给出锚定的动态版本——公众用递归最小二乘学习政策规则，通胀停在该处久了，认为它会停在原处的信心才累积起来；锚是学出来的，不是宣布出来的。</p><p><span class="marginnote">直觉类比：锚定像个人信誉——不是宣布一次就有的，而是每次说到做到攒出来的。通胀停在目标附近越久，公众越相信它会继续停在那里；一旦反复失约，锚就悄悄松动，重攒信誉要付通胀波动的成本。</span></p><p>公共信息的作用是另一层机制。<a href="/econ/morris-shin-public-info">Morris–Shin 公共信息</a>指出：当行动者有协调动机时，一条公开信号即使不完全，也会被过度加权——大家都推测别人在读它。央行公告因此是协调装置：通胀目标制之所以便宜地改变了预期，正是因为目标数字给了所有人同一个聚焦点。同一机制的暗面是，若公众怀疑央行自身的判断，过度协调会放大央行的错误；沟通的精确度不是越高越好，取决于公众对信号源质量的信念。锚定的实证度量交给<a href="/econ/survey-expectations">调查预期数据</a>：专业预测者离散度的收窄与长期预测对目标的收敛，是锚定与否的直接读数。</p>',4)),(e(),t(r,null,{default:a(()=>[B(n,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20ANN%5B%22%E5%A4%AE%E8%A1%8C%E5%85%AC%E5%91%8A%EF%BC%9A%E4%B8%80%E6%9D%A1%E5%85%AC%E5%BC%80%E4%BF%A1%E5%8F%B7%22%5D%20--%3E%20KNOW%5B%22%E4%BA%BA%E4%BA%BA%E9%83%BD%E7%9F%A5%E9%81%93%E5%88%AB%E4%BA%BA%E4%B9%9F%E5%9C%A8%E8%AF%BB%22%5D%0A%20%20KNOW%20--%3E%20OVERW%5B%22%E4%BF%A1%E5%8F%B7%E5%9B%A0%E5%8D%8F%E8%B0%83%E5%8A%A8%E6%9C%BA%E8%A2%AB%E8%BF%87%E5%BA%A6%E5%8A%A0%E6%9D%83%22%5D%0A%20%20OVERW%20--%3E%20COORD%5B%22%E9%A2%84%E6%9C%9F%E5%8D%8F%E8%B0%83%E5%88%B0%E5%AE%A3%E5%B8%83%E7%9A%84%E7%9B%AE%E6%A0%87%22%5D%0A%20%20COORD%20--%3E%20ANCHOR%5B%22%E9%94%9A%E5%AE%9A%E4%BB%A5%E4%BD%8E%E6%88%90%E6%9C%AC%E5%BB%BA%E7%AB%8B%22%5D%0A%20%20SUS%7B%22%E5%85%AC%E4%BC%97%E6%80%80%E7%96%91%E4%BF%A1%E5%8F%B7%E6%BA%90%EF%BC%9F%22%7D%0A%20%20SUS%20--%20%22%E5%90%A6%22%20--%3E%20ANCHOR%0A%20%20SUS%20--%20%22%E6%98%AF%22%20--%3E%20DARK%5B%22%E5%90%8C%E4%B8%80%E6%9C%BA%E5%88%B6%E6%94%BE%E5%A4%A7%E5%A4%AE%E8%A1%8C%E7%9A%84%E9%94%99%E8%AF%AF%22%5D%0A"})]),fallback:a(()=>[...E[1]||(E[1]=[o(" Loading... ",-1)])]),_:1})),E[4]||(E[4]=A('<p><span class="marginnote">锚定的算术：预期通胀锚住时，名义利率降一百基点，实际利率约降一百基点；预期脱锚时，宽松的一部分被预期通胀上升抵消。2021 至 2023 年关于通胀是否脱锚的争论，争的就是这个泄漏项的大小。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不重推导欧拉方程与菲利普斯曲线的微观基础，也不展开开放经济的汇率渠道——<a href="/econ/uip-and-cip">利率平价与汇率</a>已另有安排。要钉住的边界是：预期管理不能替代承诺的可信性，指引只有在与规则一致时才被定价；诊断性预期（<a href="/econ/diagnostic-expectations">过度外推与诊断性信念</a>）提醒短期预期会系统性外推近期状态，这使锚定度量必须区分短期波动与长期锚。下一课把传导推到极限状态：当短端利率触到下限，管道还剩什么。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>传导由三段组成：预期利率路径、锚定的实际利率折算、家庭结构的分布效应。</li><li>标准代表性家庭模型放大前瞻指引，HANK 类模型把它修正到合理量级。</li><li>锚定是学习出来的均衡，不是公告的瞬时效果；公共信号因协调而被过度加权。</li><li>沟通的精确度有最优水平：公众怀疑信号源时，过度协调放大央行错误。</li><li>出处：Woodford, <em>Interest and Prices</em>, 2003；Morris–Shin 2002；Eggertsson–Woodford 2003；Kaplan–Moll–Violante 2018。</li></ul>',5))])}const F=i(p,[["render",d]]);export{D as __pageData,F as default};
